using System;using System.Threading;using Autodesk.Revit.ApplicationServices;using Autodesk.Revit.DB;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.Core.Services;
public sealed class JobProcessor:IJobProcessor { readonly IDocumentOpener opener;readonly ITemporaryViewBuilder builder;readonly INwcExporter exporter;public JobProcessor(IDocumentOpener o,ITemporaryViewBuilder b,INwcExporter e){opener=o;builder=b;exporter=e;}public ExportResult Process(FederationJob j,Application app,IProgress<string>? p,CancellationToken t){Document? d=null;try{t.ThrowIfCancellationRequested();j.Status=JobStatus.Opening;p?.Report("Opening model");d=opener.Open(j.Model,app);t.ThrowIfCancellationRequested();j.Status=JobStatus.BuildingView;p?.Report("Creating temporary view");var v=builder.Create(d);t.ThrowIfCancellationRequested();j.Status=JobStatus.Exporting;p?.Report("Exporting NWC");return exporter.Export(d,v,j);}catch(OperationCanceledException){j.Status=JobStatus.Cancelled;throw;}catch(Exception ex){return ExportResult.Fail(ex.Message);}finally{if(d!=null&&d.IsValidObject){j.Status=JobStatus.Closing;p?.Report("Closing without save");d.Close(false);}}} }
